// src/pages/DeliveryDashboardPage.tsx
import React, { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import axios from 'axios';

interface Delivery {
  _id: string;
  customerId: string;
  address: string;
  status: string;
}

export default function DeliveryDashboardPage() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const navigate = useNavigate();

  // fetch your data however you do
  useEffect(() => {
    axios.get<Delivery[]>('/api/delivery')
      .then(res => setDeliveries(res.data))
      .catch(console.error);
  }, []);

  // simple inline styles to illustrate light-blue header/footer
  const headerFooterStyle: React.CSSProperties = {
    background: '#e0f7fa',
    padding: '10px 20px',
    display: 'flex',
    alignItems: 'center',
    gap: '10px'
  };

  const buttonStyle: React.CSSProperties = {
    padding: '8px 16px',
    border: 'none',
    borderRadius: 4,
    cursor: 'pointer',
    background: '#0288d1',
    color: '#fff'
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      {/* HEADER */}
      <header style={headerFooterStyle}>
        <button
          type="button"
          style={buttonStyle}
          onClick={() => navigate('/delivery/new')}
        >
          + New Delivery
        </button>
        <button
          type="button"
          style={buttonStyle}
          onClick={() => navigate('/driver/new')}
        >
          + Add Driver
        </button>
        <button
          type="button"
          style={buttonStyle}
          onClick={() => navigate('/drivers')}
        >
          View Drivers
        </button>
        <button
          type="button"
          style={buttonStyle}
          onClick={() => navigate('/analytics')}
        >
          📊 Analytics
        </button>
      </header>

      {/* MAIN CONTENT */}
      <main style={{ flex: 1, padding: '20px' }}>
        <h2>🚚 Deliveries</h2>
        {deliveries.length === 0 ? (
          <p>No deliveries found.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Customer</th>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Address</th>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Status</th>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {deliveries.map(d => (
                <tr key={d._id}>
                  <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{d.customerId}</td>
                  <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{d.address}</td>
                  <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>{d.status}</td>
                  <td style={{ padding: '8px', borderBottom: '1px solid #eee' }}>
                    <Link to={`/delivery/${d._id}`} style={{ marginRight: 8 }}>View</Link>
                    <button
                      type="button"
                      onClick={() => navigate(`/delivery/${d._id}/edit`)}
                      style={{ ...buttonStyle, padding: '4px 8px', fontSize: '0.9em' }}
                    >
                      Edit
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </main>

      {/* FOOTER */}
      <footer style={headerFooterStyle}>
        <span>© 2025 Delivery Dashboard</span>
        <button
          type="button"
          style={{ marginLeft: 'auto', ...buttonStyle }}
          onClick={() => navigate('/drivers')}
        >
          View Drivers
        </button>
      </footer>
    </div>
  );
}
